DELETE FROM public.jobs WHERE 'Passion: Tennis' = ANY(tags) AND (lower(title) LIKE '%landlord%' OR lower(title) LIKE '%tenant%' OR lower(title) LIKE '%lettings%' OR lower(title) LIKE '%leasehold%' OR lower(title) LIKE '%property%' OR lower(company) LIKE '%property%' OR lower(description) LIKE '%landlord and tenant act%' OR lower(description) LIKE '%lettings%' OR lower(description) LIKE '%property litigation%' OR lower(description) LIKE '%leasehold%');